def issue_refund(order_id: str, amount: float, session) -> dict:
    if not session.identity_verified:            # ordering enforced in code
        return {"is_error": True, "content": "Verify identity first"}
    order = orders.get(order_id)
    if order is None or order.customer_id != session.customer_id:
        return {"is_error": True, "content": "Order not found"}
    if amount > 500:                               # cap enforced, not prompted
        return approvals.request(order_id, amount)  # pending human approval
    return payments.refund(order_id, amount)

def route(item):
    if item.validation_errors or item.stated_total != sum(item.lines):
        return "review", "validation"
    risky = [f for f, c in item.conf.items() if c < CALIBRATED[f]]
    if risky or item.amount > 10_000:
        return "review", risky or "high_value"
    if sampler.pick(stratum=item.segment, rate=0.03):
        return "review", "audit_sample"
    return "accept", None

ALLOWED_FEATURES = {"messages", "prompt_caching", "citations"}  # reviewed vs eligibility table

def pre_send(req):
    used = detect_features(req)
    if not used <= ALLOWED_FEATURES:
        raise ComplianceError(f"not approved: {used - ALLOWED_FEATURES}")
    if PAN_RE.search(req.text) and luhn_ok(req.text):
        raise ComplianceError("card number in prompt")
    audit.write(req.id, model=req.model, prompt_ver=req.template_version,
                doc_ids=req.retrieved_ids)  # no raw content

base = load_cases("tenant_screening_eval.jsonl")
variants = {"name": NAMES_BY_GROUP, "postcode": POSTCODES_BY_AREA}
for case in base:
    for attr, values in variants.items():
        outs = [score(case.with_(attr, v)) for v in values]
        gaps[attr].append(max(outs) - min(outs))
report({a: (mean(g), pct_over(g, 0.05)) for a, g in gaps.items()})
assert all(mean(g) < 0.02 for g in gaps.values())  # CI regression gate
